def _get_scoped_trace_graph(module: nn.Module, inputs: Union[Tensor, Tuple[
    Tensor, ...]], aliases: Dict[Union[str, nn.Module], str]) ->torch._C.Graph:
    class ScopePushHook:
        def __init__(self, name: str) -> None:
            self.name = name

        def __call__(self, module: nn.Module, inputs: Any) -> None:
            tracing_state = torch.jit._get_tracing_state()
            if tracing_state:
                tracing_state.push_scope(self.name)

    class ScopePopHook:
        def __call__(self, module: nn.Module, inputs: Any, outputs: Any) -> None:
            tracing_state = torch.jit._get_tracing_state()
            if tracing_state:
                tracing_state.pop_scope()

    hooks = []
    for mod in module.modules():
        if mod in aliases:
            name = aliases[mod]
        else:
            continue
        hooks.append(mod.register_forward_pre_hook(ScopePushHook(name)))
        hooks.append(mod.register_forward_hook(ScopePopHook()))

    if isinstance(inputs, Tensor):
        inputs = (inputs,)

    try:
        graph, _ = _get_trace_graph(module, inputs)
    finally:
        for hook in hooks:
            hook.remove()

    return graph
